export function continueHomeLabels(language='EN'){const i=Math.max(0,continueHomeLanguages.indexOf(language));return Object.fromEntries(Object.entries(homeWords).map(([key,row])=>[key,row.split('|')[i]||row.split('|')[0]]));}

export function attachContinueHome({getLanguage=()=> 'EN',readWorkData=()=>({}),onResume=()=>false,onSeriesPublication=()=>false,setMode=()=>{},storage=globalThis.localStorage}={}){
 const host=document.querySelector('.hero')||document.querySelector('.custom-library-toolbar');if(!host||document.getElementById('continue-home'))return null;
 const store=createContinueStore(storage);let prefs=store.read(),noteDraft=prefs.note,startDraft=prefs.showOnStart,pending=false,query='',showTools=false,statusKey=store.problem()?'saveError':'',workTimer=null;
 const t=()=>continueHomeLabels(getLanguage()),el=(tag,text='',cls='')=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
 const root=el('details','','continue-home');root.id='continue-home';root.open=prefs.showOnStart;const summary=el('summary'),body=el('div','','ch-body');root.append(summary,body);host.after(root);
 const launcher=el('button');launcher.id='continue-home-launcher';launcher.type='button';launcher.addEventListener('click',()=>{root.open=true;root.scrollIntoView({behavior:'smooth',block:'start'});});document.querySelector('.custom-library-toolbar')?.append(launcher);
 const status=el('p','','ch-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');let workList,favoriteList,toolList;
 const notify=key=>{statusKey=key;status.textContent=t()[key]||'';};
 function persist(patch){try{prefs=store.update({...patch,note:noteDraft,showOnStart:startDraft});pending=false;notify('saved');return true;}catch(error){pending=true;notify(error.message==='conflict'?'conflict':'saveError');return false;}}
 function button(parent,key,fn){const b=el('button',t()[key]);b.type='button';b.dataset.homeAction=key;b.addEventListener('click',fn);parent.append(b);return b;}
 function jump(id){if(!openContinueTool(id,{setMode}))notify('missing');}
 function favorite(id){const next=prefs.favorites.includes(id)?prefs.favorites.filter(x=>x!==id):[...prefs.favorites,id];if(next.length>6){notify('maxFavorites');return;}if(persist({favorites:next})){renderFavorites();renderTools();}}
 function renderFavorites(){favoriteList.replaceChildren();for(const id of prefs.favorites){const tool=continueHomeTools.find(t=>t.id===id);if(!tool)continue;const b=el('button',continueToolLabel(tool,getLanguage()));b.type='button';b.dataset.homeTool=id;b.addEventListener('click',()=>jump(id));favoriteList.append(b);}}
 function renderTools(){toolList.replaceChildren();if(!query.trim()&&!showTools)return;const tools=query.trim()?searchContinueTools(query,getLanguage()):continueHomeTools;if(!tools.length){toolList.append(el('p',t().noResults));return;}for(const tool of tools){const row=el('div','','ch-tool-row'),open=el('button',continueToolLabel(tool,getLanguage())),pin=el('button',prefs.favorites.includes(tool.id)?'★':'☆');open.type=pin.type='button';open.dataset.homeTool=tool.id;pin.dataset.homePin=tool.id;pin.title=t()[prefs.favorites.includes(tool.id)?'unpin':'pin'];pin.setAttribute('aria-label',pin.title+' · '+continueToolLabel(tool,getLanguage()));pin.setAttribute('aria-pressed',String(prefs.favorites.includes(tool.id)));open.addEventListener('click',()=>jump(tool.id));pin.addEventListener('click',()=>favorite(tool.id));row.append(open,pin);toolList.append(row);}}
 function call(action){try{action();}catch{notify('missing');}}
 function refreshWorks(){if(!workList)return;let data;try{data=readWorkData()||{};}catch{data={errors:true};}workList.replaceChildren();if(data.errors)notify('dataError');const cards=continueWorkCards(data,prefs);if(!cards.length){workList.append(el('p',t().empty));return;}for(const work of cards){const card=el('article','','ch-work');card.dataset.homeWork=work.kind+':'+work.id;card.append(el('small',t()[work.kind]),el('h3',work.title||t()[work.kind]));
  if(work.kind==='series'){card.append(el('p',t().progress.replace('{done}',work.completed).replace('{total}',work.total)));if(work.nextScene)card.append(el('p',t().nextScene+work.nextScene));card.append(el('p',t()[['none','working','ready','stale'].includes(work.publication)?work.publication:'none']));}
  else if(work.kind==='trial')card.append(el('p',t().trialProgress.replace('{done}',work.completed).replace('{total}',work.total)));
  else card.append(el('p',work.ready?t().ready:t()[{image:'nextImage',audio:'nextAudio',cover:'nextCover',text:'nextText',copy:'nextCopy',source:'nextSource'}[work.nextCheck]||'working']));
  const actions=el('div','','ch-actions');button(actions,'continue',()=>call(()=>onResume(work.kind,work.id)));if(work.kind==='series')button(actions,'openPublication',()=>call(()=>onSeriesPublication(work.id)));card.append(actions);workList.append(card);
 }}
 function render(){summary.textContent=t().title;launcher.textContent=t().title;body.replaceChildren(el('p',t().intro));
  const header=el('div','','ch-actions'),startLabel=el('label','','ch-check'),start=el('input');start.type='checkbox';start.checked=startDraft;start.dataset.homeField='showOnStart';start.addEventListener('change',()=>{startDraft=start.checked;persist({showOnStart:startDraft});});startLabel.append(start,el('span',t().showOnStart));header.append(startLabel);button(header,'refresh',refreshWorks);body.append(header);
  const noteLabel=el('label','','ch-note');noteLabel.append(el('span',t().note));const note=el('textarea');note.rows=2;note.maxLength=1500;note.value=noteDraft;note.placeholder=t().noteHint;note.dataset.homeField='note';note.addEventListener('input',()=>{noteDraft=note.value;persist({note:noteDraft});});noteLabel.append(note);body.append(noteLabel);const noteActions=el('div','','ch-actions');button(noteActions,'save',()=>persist({note:noteDraft,showOnStart:startDraft}));button(noteActions,'copyNote',async()=>{try{await navigator.clipboard.writeText(noteDraft);notify('copied');}catch{notify('saveError');}});body.append(noteActions);
  body.append(el('h3',t().recent),el('p',t().recentHelp,'ch-help'));workList=el('div','','ch-work-grid');body.append(workList);
  body.append(el('h3',t().favorites));favoriteList=el('div','','ch-favorites');body.append(favoriteList);
  const searchLabel=el('label','','ch-search');searchLabel.append(el('span',t().search));const search=el('input');search.type='search';search.maxLength=160;search.value=query;search.placeholder=t().searchHint;search.dataset.homeField='search';search.addEventListener('input',()=>{query=search.value;renderTools();});searchLabel.append(search);body.append(searchLabel);
  const listLabel=el('label','','ch-check'),list=el('input');list.type='checkbox';list.checked=showTools;list.dataset.homeField='tools';list.addEventListener('change',()=>{showTools=list.checked;renderTools();});listLabel.append(list,el('span',t().tools));body.append(listLabel);toolList=el('div','','ch-tools');body.append(toolList,status);status.textContent=t()[statusKey]||'';renderFavorites();renderTools();refreshWorks();
 }
 const workChanged=event=>{const detail=event.detail||{};try{store.touch(detail.kind,detail.id);prefs=store.read();}catch{notify('saveError');}clearTimeout(workTimer);workTimer=setTimeout(refreshWorks,150);};
 document.addEventListener('prompt-studio-work-changed',workChanged);document.addEventListener('prompt-studio-work-opened',workChanged);
 document.getElementById('ui-language')?.addEventListener('change',render);
 globalThis.addEventListener?.('storage',event=>{if(event.key===continueHomeKey)notify('conflict');else if(event.key==='artoftomworks.v2.trialBench'||event.key==='artoftomworks.v2.seriesPlanner'||event.key==='artoftomworks.v2.publicationDesk')refreshWorks();});
 globalThis.addEventListener?.('beforeunload',event=>{if(pending){event.preventDefault();event.returnValue='';}});
 render();return {refresh:refreshWorks,getPreferences:()=>({...prefs,note:noteDraft,showOnStart:startDraft}),translate:render};
}
